const TB=(h,rows)=>`<div class="tbl"><table><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const W1=`<h2>Worked call-outs</h2><p class="goal">Three realistic calls, from first phone call to handover.</p>
<h3>Scenario 1: nail in the tread, quiet side road, daytime</h3>
<ul><li><b>The call:</b> “My tyre is going soft. I see a nail.” You note name, number, a shared location pin, the vehicle, the tyre size and that the spare is fine.</li>
<li><b>Triage:</b> Normal priority. Safe place, daytime, slow leak. Quote the call-out fee and a plug repair, and give an honest arrival time.</li>
<li><b>On arrival:</b> Park behind, hazards on, triangle placed, wheels chocked. Check around the tyre. The nail is in the tread, well away from the shoulder.</li>
<li><b>Decision:</b> Hole is the size of the nail, tread area, tyre not driven flat. Repairable, so do a string plug on the spot.</li>
<li><b>Handover:</b> Soapy-water check, correct pressure, valve cap on. Tell the customer to get a full patch-plug soon and to drive gently. Confirm payment on your phone. Log the job.</li></ul>
<h3>Scenario 2: sidewall bulge on the highway, night</h3>
<ul><li><b>The call:</b> “I hit a pothole and there is a bulge on the side.” This is urgent: highway, night.</li>
<li><b>Safety first:</b> Ask them to keep hazards on, stand well off the road behind a barrier and not to change the wheel themselves. Do not tell them to drive on.</li>
<li><b>Decision:</b> A sidewall bulge cannot be repaired. Options: fit the spare if it is sound, or tow if the rim may be bent.</li>
<li><b>On arrival:</b> Place the triangle early, well before the bend, wear your vest and use a torch. Inspect the rim edge. If the rim is bent, the answer is a tow, not a wheel change.</li>
<li><b>Handover:</b> Show the customer the bulge, explain why it is unsafe, and quote replacement or tow separately. Do not pressure them.</li></ul>
<h3>Scenario 3: flat tyre, spare is flat, locking nut key missing</h3>
<ul><li><b>The call:</b> You ask “Do you have a spare and the locking nut key?” The answer is “The spare looks soft and I cannot find the key.”</li>
<li><b>Plan before leaving:</b> Bring a plug kit for the spare, the removal tool for locking nuts and your compressor. Tell the customer to check the glovebox and boot.</li>
<li><b>On site:</b> If the key is found, remove the wheel. If not, use the removal tool. If the nut will not move, stop and arrange a tow.</li>
<li><b>The spare:</b> Check it for a small tread hole. If it is repairable, plug it and inflate it to the correct pressure. If not, tow.</li>
<li><b>Handover:</b> Remind them to re-check nuts after 50 to 100 km and to get the original tyre repaired or replaced.</li></ul>`;
const W2=`<h3>Troubleshooting table</h3>`+TB(['Problem','Likely cause','What to do'],[
['Air leaks around the plug','Hole larger than 6 mm or angled, plug too small, or a second object','Stop. If within limits, remove the tyre and fit a patch-plug. Otherwise replace the tyre.'],
['Patch lifts at the edges','Poor buffing, wet or dusty cement, or the patch is too small','Remove it, rebuff a wider area, apply fresh cement, let it dry and use a larger patch.'],
['Bubbles at the bead after fitting','Rust or dirt on the bead seat, or a dry bead','Deflate, clean the seat with a wire brush, lubricate and reseat.'],
['Slow pressure drop overnight','Valve core, rim corrosion, or a second puncture','Check the valve, bead and the whole tread with soapy water.'],
['Vibration after the repair','Plug stem left long, or the wheel is out of balance','Trim the stem flush and rebalance the wheel.'],
['Cold patch will not stick','Cement dried out in the tube, or the surface is greasy','Use fresh cement and clean and rebuff the area.'],
['Tube fails again at the same place','Object still inside the tyre, or a sharp rim edge','Check inside the tyre and run a hand around the rim and rim tape.']]);
const W3=`<h2>Pricing worked example</h2><p class="goal">The numbers are examples in currency units. Replace them with your own local prices.</p>
<h3>Cost of one plug repair job</h3>`+TB(['Item','Cost'],[['Materials (plug, cement, soap)','2'],['Fuel or transport','3'],['Your time (1 hour at 6 per hour)','6'],['<b>Cost per job</b>','<b>11</b>']])+
`<h3>Fixed costs each month</h3><p>Tool replacement 20 and phone data 5, so <b>25 a month</b>. At 20 jobs this adds about 1.25 to each job.</p>
<h3>Set the price</h3>`+TB(['Price plan','Income per job','Profit per job','Verdict'],[['Plug repair only at 10','10','-1 (loss)','Does not cover the cost of travel'],['Call-out fee 10 plus repair 6','16','16 - 11 - 1.25 = 3.75','Healthy'],['Call-out fee 10 plus repair 6, with a 5 discount','11','-1.25','Loss. Never discount below cost']])+
`<h3>Break-even and a monthly view</h3><ul><li><b>Break-even:</b> fixed costs 25 divided by profit before fixed costs (16 - 11 = 5) is <b>5 jobs</b>. After the fifth job each month, you are in profit.</li><li><b>40 jobs a month:</b> income 640, job costs 440, fixed costs 25, so profit is <b>175</b>.</li><li><b>Quiet month, 15 jobs:</b> income 240, job costs 165, fixed costs 25, so profit is <b>50</b>. Keep a small reserve for these months.</li></ul>
<h3>Rules to remember</h3><ul><li>Quote the call-out fee and repair separately.</li><li>Charge more at night or on the highway, because the risk and time are higher.</li><li>Keep a record of each job so you can see which jobs earn the most.</li></ul>`;
const W4=`<h3>Worked example: tow or repair?</h3><ul><li><b>Situation:</b> A taxi hit a kerb. The tyre is flat and the outer sidewall is scuffed. The driver drove 2 km on the flat tyre.</li><li><b>Check 1, is the location safe?</b> It is a busy junction, so ask them to move to the side if possible.</li><li><b>Check 2, tyre:</b> Dark dust inside and a scuffed sidewall mean it was driven flat. Not repairable.</li><li><b>Check 3, rim:</b> The edge is bent and the wheel will not hold air at the bead. Not usable.</li><li><b>Check 4, spare:</b> It is sound, but the bent rim and possible suspension damage make driving unsafe.</li><li><b>Decision:</b> Tow. Show the damage, explain it, and offer the tow price and a replacement price separately.</li></ul>`;
sub('s2t2',n=>n+W1);sub('s2t1',n=>n+W2);sub('s3t6',n=>n+W3);sub('s3t5',n=>n+W4);
